def transform(grid):
    h,w=len(grid),len(grid[0])
    rows={i for i,row in enumerate(grid) if len(set(row))==1}
    cols={j for j in range(w) if len({row[j] for row in grid})==1}
    return [[2 if (i in rows or j in cols) else v for j,v in enumerate(row)] for i,row in enumerate(grid)]

